const input = JSON.parse(query);
const salesData = input.salesData || [];

const weights = { volume: 0.40, coverage: 0.30, growth: 0.20, returns: 0.10 };
const distributors = [];

salesData.forEach(row => {
  const sales = parseFloat(row.Sales_Value_PKR);
  const target = parseFloat(row.Weekly_Target_PKR);
  const outlets = parseFloat(row.Outlets_Covered);
  const outletsTarget = parseFloat(row.Outlets_Target);
  const returns = parseFloat(row.Returns_PKR || 0);
  const historicalSales = parseFloat(row.Historical_Sales_PKR || 0);

  const volumePct = target > 0 ? (sales / target) * 100 : 0;
  const coveragePct = outletsTarget > 0 ? (outlets / outletsTarget) * 100 : 0;
  const growthPct = historicalSales > 0 ? ((sales - historicalSales) / historicalSales) * 100 : 0;
  const returnsPct = sales > 0 ? (returns / sales) * 100 : 0;

  const compositeScore = 
    (volumePct * weights.volume) +
    (coveragePct * weights.coverage) +
    (growthPct * weights.growth) +
    ((100 - returnsPct) * weights.returns);

  let tier = "Critical";
  if (compositeScore >= 80) tier = "Elite";
  else if (compositeScore >= 60) tier = "On Track";
  else if (compositeScore >= 40) tier = "At Risk";

  distributors.push({
    distributor_code: row.Distributor_Code,
    sales: sales,
    target: target,
    volume_pct: Math.round(volumePct * 10) / 10,
    coverage_pct: Math.round(coveragePct * 10) / 10,
    growth_pct: Math.round(growthPct * 10) / 10,
    returns_pct: Math.round(returnsPct * 10) / 10,
    composite_score: Math.round(compositeScore * 10) / 10,
    tier: tier
  });
});

distributors.sort((a, b) => b.composite_score - a.composite_score);
distributors.forEach((d, i) => { d.rank = i + 1; });

return JSON.stringify({
  distributors: distributors,
  topPerformer: distributors[0],
  bottomPerformer: distributors[distributors.length - 1]
});

const input = JSON.parse(query);
const distributors = input.distributors || [];

const commentary = distributors.map(d => ({
  distributor_code: d.distributor_code,
  observation: `${d.distributor_code} achieved a composite score of ${d.composite_score} placing them in ${d.tier} tier. Volume achievement at ${d.volume_pct}% and coverage at ${d.coverage_pct}% demonstrate ${d.tier === "Elite" ? "exceptional" : d.tier === "Critical" ? "concerning" : "solid"} performance.`,
  recommendation: d.tier === "Elite" ? "Maintain excellence and share best practices with underperforming distributors." : d.tier === "Critical" ? "Immediate intervention required. Schedule urgent review meeting to address all KPI gaps." : "Focus improvement efforts on lowest performing metrics to reach Elite tier."
}));

const executiveBrief = `Weekly scorecard processed for ${distributors.length} distributors. Top performer: ${distributors[0]?.distributor_code || "N/A"} with score ${distributors[0]?.composite_score || 0}. Bottom performer: ${distributors[distributors.length - 1]?.distributor_code || "N/A"} with score ${distributors[distributors.length - 1]?.composite_score || 0}. ${distributors.filter(d => d.tier === "Critical").length} distributors require immediate attention.`;

return JSON.stringify({
  distributor_commentary: commentary,
  executive_brief: executiveBrief
});

return [{
  json: {
    body: {
      query: "Run full weekly automation: get data, calculate scores, generate AI commentary, send all distributor emails, and send NSM report"
    },
    sessionId: "scheduled-automation"
  }
}];

const input = JSON.parse(query);
const allRows = input.rows || [];

const today = new Date();
const lastSunday = new Date(today);
lastSunday.setDate(today.getDate() - today.getDay());
lastSunday.setHours(0, 0, 0, 0);

const weekStart = new Date(lastSunday);
weekStart.setDate(lastSunday.getDate() - 6);

const weekEnd = lastSunday.toISOString().split("T")[0];

const filteredRows = allRows.filter(row => {
  if (!row.Week_End_Date) return false;
  const rowDate = new Date(row.Week_End_Date);
  return rowDate >= weekStart && rowDate <= lastSunday;
});

return JSON.stringify({
  rows: filteredRows,
  weekEnd: weekEnd,
  rowCount: filteredRows.length
});

const input = JSON.parse(query);
const rows = input.rows || [];
const distributorConfig = input.distributorConfig || [];

const validRows = [];
const errorRows = [];

const configMap = {};
distributorConfig.forEach(d => {
  if (d.Distributor_Code) {
    configMap[d.Distributor_Code] = d;
  }
});

rows.forEach((row, index) => {
  const errors = [];

  if (!row.Distributor_Code) errors.push("Missing Distributor_Code");
  if (!row.Sales_Value_PKR) errors.push("Missing Sales_Value_PKR");
  if (!row.Weekly_Target_PKR) errors.push("Missing Weekly_Target_PKR");
  if (!row.Outlets_Covered) errors.push("Missing Outlets_Covered");
  if (!row.Outlets_Target) errors.push("Missing Outlets_Target");
  if (!row.Week_End_Date) errors.push("Missing Week_End_Date");

  if (row.Sales_Value_PKR && isNaN(parseFloat(row.Sales_Value_PKR))) {
    errors.push("Invalid Sales_Value_PKR (not numeric)");
  }
  if (row.Weekly_Target_PKR && isNaN(parseFloat(row.Weekly_Target_PKR))) {
    errors.push("Invalid Weekly_Target_PKR (not numeric)");
  }
  if (row.Outlets_Covered && isNaN(parseFloat(row.Outlets_Covered))) {
    errors.push("Invalid Outlets_Covered (not numeric)");
  }
  if (row.Outlets_Target && isNaN(parseFloat(row.Outlets_Target))) {
    errors.push("Invalid Outlets_Target (not numeric)");
  }

  if (row.Week_End_Date && !/^\d{4}-\d{2}-\d{2}$/.test(row.Week_End_Date)) {
    errors.push("Invalid date format (expected YYYY-MM-DD)");
  }

  if (row.Distributor_Code && !configMap[row.Distributor_Code]) {
    errors.push("Distributor not found in config");
  }

  const config = configMap[row.Distributor_Code];
  if (config && config.Active !== "YES") {
    errors.push("Distributor not active");
  }

  if (errors.length > 0) {
    errorRows.push({
      row_number: index + 1,
      distributor_code: row.Distributor_Code || "UNKNOWN",
      error_type: "VALIDATION_FAILED",
      detail: errors.join("; "),
      date: new Date().toISOString().split("T")[0]
    });
  } else {
    validRows.push(row);
  }
});

return JSON.stringify({
  validRows: validRows,
  errorRows: errorRows,
  validCount: validRows.length,
  errorCount: errorRows.length
});

const input = JSON.parse(query);
const reportLog = input.reportLog || [];
const weekEnd = input.weekEnd;

const isDuplicate = reportLog.some(log => log.week_end === weekEnd);

return JSON.stringify({
  isDuplicate: isDuplicate,
  message: isDuplicate ? `Report already exists for week ending ${weekEnd}` : "No duplicate found, safe to proceed"
});
